APP_TITLE = 'APhO 2026 Experiment 1 — Water Clock (HaslaLab)'
G = 981.0
D_VALVE, D_HOLE4, D_HOLE5 = (0.4, 0.4, 0.5)
A_VALVE = math.pi * (D_VALVE / 2) ** 2
A_HOLE4 = math.pi * (D_HOLE4 / 2) ** 2
A_HOLE5 = math.pi * (D_HOLE5 / 2) ** 2
KV, XV = (26.8, 0.535)
CD_HOLE = 0.8
SIGMA = 72.0
MENISCUS = 0.22
H_STOP4 = SIGMA / (1.0 * G * (D_HOLE4 / 2.0))
H_STOP5 = SIGMA / (1.0 * G * (D_HOLE5 / 2.0))
T_WATER = 22.0
DCD_DT = 0.0006
TANK_TOL = 0.02
CD_B5 = 0.733
TANK_W, TANK_D = (10.0, 10.0)
TANK_AREA = TANK_W * TANK_D
WALL = 0.5
A_INNER_H = 15.1
A_OUT_Z = 1.0
A_RIM = A_INNER_H - A_OUT_Z
A_CAP = TANK_AREA * A_INNER_H
N_MARKS = 13
B_INNER_H = 15.2
B_HOLE_Z = 0.7
B_CAP = TANK_AREA * B_INNER_H
BOTTLE_CAP, BEAKER_CAP = (2000.0, 250.0)
POUR_MAX = 240.0
POUR_START = 0.12
PUMP_RATE = 150.0
PUMP_STROKE_T = 0.55
RIGID_LEN = 40.0
HOSE_LEN = 100.0
SLOSH_V0 = 20.0
BOTTLE_POLY = ((-3.7, 0.3), (3.7, 0.3), (3.7, 15.0), (2.0, 17.5), (1.35, 21.4), (-1.35, 21.4), (-2.0, 17.5), (-3.7, 15.0))
BOTTLE_LIP = (0.0, 22.6)
A_NECK = math.pi * 1.1 ** 2
CD_NECK = 0.35
BEAKER_POLY = ((-3.15, 0.2), (3.15, 0.2), (4.05, 9.5), (-4.05, 9.5))
BEAKER_LIP = (4.4, 9.7)
A_LIP = 2.6
CD_LIP = 0.45

def rot(pts, a):
    ca, sa = (math.cos(a), math.sin(a))
    return [(x * ca - y * sa, x * sa + y * ca) for x, y in pts]

def poly_area(pts):
    n = len(pts)
    return 0.5 * abs(sum((pts[i][0] * pts[(i + 1) % n][1] - pts[(i + 1) % n][0] * pts[i][1] for i in range(n))))

def clip_below(pts, nx, ny, d):
    """the part of the polygon on the lower side of the line n.p = d."""
    out = []
    n = len(pts)
    for i in range(n):
        a, b = (pts[i], pts[(i + 1) % n])
        da = nx * a[0] + ny * a[1] - d
        db = nx * b[0] + ny * b[1] - d
        if da <= 0:
            out.append(a)
        if da < 0 < db or db < 0 < da:
            t = da / (da - db)
            out.append((a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1])))
    return out

def fill_line(pts, frac, nx=0.0, ny=1.0):
    """offset d of the free surface so that the wetted area is `frac` of the
    whole cross-section:  the water level of a partly filled vessel, at any
    inclination."""
    frac = max(0.0, min(1.0, frac))
    total = poly_area(pts)
    if total <= 0 or frac <= 0:
        return min((nx * x + ny * y for x, y in pts)) - 1e-06
    if frac >= 1.0:
        return max((nx * x + ny * y for x, y in pts)) + 1e-06
    lo = min((nx * x + ny * y for x, y in pts))
    hi = max((nx * x + ny * y for x, y in pts))
    for _ in range(26):
        mid = 0.5 * (lo + hi)
        a = poly_area(clip_below(pts, nx, ny, mid))
        if a < frac * total:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)

def vessel_geom(src):
    if src == 'beaker':
        return (BEAKER_POLY, BEAKER_LIP, BEAKER_CAP)
    return (BOTTLE_POLY, BOTTLE_LIP, BOTTLE_CAP)
PUDDLE_T = 0.22
PUDDLE_SPREAD = 7.0
BIN_X0, BIN_X1 = (3.0, 48.0)
BIN_Z0, BIN_Z1 = (0.0, 28.0)
BIN_H, BIN_WALL, BIN_FLOOR = (16.0, 0.6, 0.6)
BIN_IW, BIN_ID = (BIN_X1 - BIN_X0 - 2 * BIN_WALL, BIN_Z1 - BIN_Z0 - 2 * BIN_WALL)
BIN_AREA = BIN_IW * BIN_ID
FLOAT_DEPTH = 2.2
BASE_W, BASE_D, BASE_T = (30.0, 22.0, 1.2)
PEDAL_NOM, PEDAL_STEP = (3.0, 0.02)
PEDAL_MIN, PEDAL_MAX = (2.2, 3.8)
ST_W, ST_D = (25.0, 12.0)
ST_STEP_X = 13.0
ST_TALL_H = 27.0
ST_STEP_H = 9.0
SLOT = {'base': {'desk': (46.0, 1.5), 'bin': (7.0, 1.5)}, 'stand': {'desk': (47.0, 2.0), 'bin': (12.0, 8.0), 'base': (12.0, 8.0)}, 'tankA': {'desk': (48.0, 2.0), 'bin': (28.0, 5.0), 'base': (28.0, 3.0)}, 'tankB': {'desk': (57.0, 2.0), 'bin': (28.0, 5.0), 'base': (28.0, 3.0)}}
DESK_TILT = (0.0004, -0.0003)
VIEW_U0, VIEW_U1 = (-5.0, 70.0)
VIEW_V0, VIEW_V1 = (-29.0, 50.0)
KC, KS = (0.91355, 0.40674)

def proj(x, y, z):
    return (KC * (x + z), y + KS * (z - x))

def mix(c1, c2, f):
    a = tuple((int(c1[i:i + 2], 16) for i in (1, 3, 5)))
    b = tuple((int(c2[i:i + 2], 16) for i in (1, 3, 5)))
    return '#%02x%02x%02x' % tuple((int(a[i] + (b[i] - a[i]) * f) for i in range(3)))

class World(object):
    """apparatus state + physics.  No tkinter."""

    def __init__(self, seed=None):
        seed = random.randrange(1 << 30) if seed is None else seed
        self.seed = seed
        self.rng = random.Random(seed)
        self.t = 0.0
        self.on = {'base': None, 'stand': None, 'tankA': None, 'tankB': None}
        self.VA = self.VB = self.Vbin = self.beaker = 0.0
        self.bottle = [BOTTLE_CAP, BOTTLE_CAP]
        self.puddles = []
        self.wiped = 0.0
        self.towel_wet = 0.0
        self.surge = {'tankA': 0.0, 'tankB': 0.0}
        self.land = {}
        self._spill_xz = None
        self._valve = False
        self._plugA4 = self._plugA5 = True
        self.plugB = True
        while True:
            self.bin_tilt = (self.rng.uniform(-0.005, 0.005), self.rng.uniform(-0.005, 0.005))
            if 0.0015 < max(abs(self.bin_tilt[0]), abs(self.bin_tilt[1])) < 0.005:
                break
        while True:
            self.pedal = [PEDAL_NOM + self.rng.uniform(-0.3, 0.3) for _ in range(4)]
            tx = (0.5 * (self.pedal[0] + self.pedal[2]) - 0.5 * (self.pedal[1] + self.pedal[3])) / BASE_W + self.bin_tilt[0]
            tz = (0.5 * (self.pedal[0] + self.pedal[1]) - 0.5 * (self.pedal[2] + self.pedal[3])) / BASE_D + self.bin_tilt[1]
            if 0.004 < max(abs(tx), abs(tz)) < 0.02:
                break
        self.wobble = 0.0
        self.pouring = None
        self.slosh = {'bottle1': 0.0, 'bottle2': 0.0, 'beaker': 0.0}
        self.pour_head = 0.0
        self.pour_tilt = 0.55
        self.pour_drop = 14.0
        self.inflight = []
        self.pump_in = None
        self.pump_out = None
        self.pumping = False
        self.run_jit = {'valve': 1.0, 'h4': 1.0, 'h5': 1.0}
        self.tw = TANK_W + self.rng.uniform(-TANK_TOL, TANK_TOL)
        self.td = TANK_D + self.rng.uniform(-TANK_TOL, TANK_TOL)
        self.area = self.tw * self.td
        self.temp = self.rng.gauss(T_WATER, 1.5)
        visc = 1.0 - DCD_DT * (self.temp - T_WATER)
        self.kv = KV * visc * self.rng.gauss(1.0, 0.0018)
        self.cd4 = CD_HOLE * visc * self.rng.gauss(1.0, 0.0018)
        self.cd5 = CD_HOLE * visc * self.rng.gauss(1.0, 0.0018)
        self.cdb = CD_B5 * visc * self.rng.gauss(1.0, 0.0018)
        self.msg = ''

    def _fresh_run(self, key):
        self.run_jit[key] = min(1.012, max(0.988, self.rng.gauss(1.0, 0.004)))

    @property
    def valve(self):
        return self._valve

    @valve.setter
    def valve(self, v):
        if v and (not self._valve):
            self._fresh_run('valve')
        self._valve = bool(v)

    @property
    def plugA4(self):
        return self._plugA4

    @plugA4.setter
    def plugA4(self, v):
        if self._plugA4 and (not v):
            self._fresh_run('h4')
        self._plugA4 = bool(v)

    @property
    def plugA5(self):
        return self._plugA5

    @plugA5.setter
    def plugA5(self, v):
        if self._plugA5 and (not v):
            self._fresh_run('h5')
        self._plugA5 = bool(v)

    @property
    def plate_y(self):
        y0 = BIN_FLOOR if self.on['base'] == 'bin' else 0.0
        return y0 + sum(self.pedal) / 4.0 + BASE_T

    def surface_y(self, s):
        if s == 'desk':
            return 0.0
        if s == 'bin':
            return BIN_FLOOR
        if s == 'base':
            return self.plate_y
        if s in ('stand_low', 'stand_high'):
            b = self.on['stand']
            if b is None:
                return None
            return self.surface_y(b) + (ST_STEP_H if s == 'stand_low' else ST_TALL_H)
        return None

    def surface_tilt(self, s):
        """(tan_x, tan_z);  positive means the +x / +z side is lower."""
        if s == 'desk':
            return DESK_TILT
        if s == 'bin':
            tx, tz = self.bin_tilt
            return (tx + self.wobble, tz + 0.6 * self.wobble)
        if s == 'base':
            left = 0.5 * (self.pedal[0] + self.pedal[2])
            right = 0.5 * (self.pedal[1] + self.pedal[3])
            front = 0.5 * (self.pedal[0] + self.pedal[1])
            back = 0.5 * (self.pedal[2] + self.pedal[3])
            bx, bz = self.surface_tilt(self.on['base'] or 'desk')
            return ((left - right) / BASE_W + bx, (front - back) / BASE_D + bz)
        if s in ('stand_low', 'stand_high'):
            return self.surface_tilt(self.on['stand'] or 'desk')
        return (0.0, 0.0)

    def slot(self, obj):
        s = self.on[obj]
        if s is None:
            return None
        if s in ('stand_low', 'stand_high'):
            st = self.slot('stand')
            if st is None:
                return None
            dx = 13.5 if s == 'stand_low' else 1.0
            return (st[0] + dx, st[1] + 0.5)
        return SLOT[obj][s]

    def obj_y(self, obj):
        s = self.on[obj]
        return None if s is None else self.surface_y(s)

    def tilt_of(self, obj):
        s = self.on[obj]
        return self.surface_tilt(s) if s else (0.0, 0.0)

    @property
    def hA(self):
        return self.VA / self.area - A_OUT_Z

    @property
    def hA_read(self):
        """What the engraved scale on the front-left corner shows.  Water that
        has just arrived has not spread across the tank yet, so the far corner
        still reads the levelled part only."""
        tx, tz = self.tilt_of('tankA')
        return (self.VA - self.surge['tankA']) / self.area - A_OUT_Z - 5.0 * tx - 5.0 * tz

    @property
    def hB(self):
        return self.VB / self.area - B_HOLE_Z

    @property
    def bin_depth(self):
        return self.Vbin / BIN_AREA

    @property
    def bin_surface_y(self):
        return BIN_FLOOR + self.bin_depth

    def outlet_y(self):
        y = self.obj_y('tankA')
        return None if y is None else y + WALL + A_OUT_Z

    def head_at(self, x_rel, z_rel):
        tx, tz = self.tilt_of('tankA')
        return self.hA + x_rel * tx + z_rel * tz

    def over_bin(self, obj):
        """does what leaves this object land inside the collection box?"""
        s = self.on[obj]
        for _ in range(6):
            if s == 'bin':
                return True
            if s == 'desk' or s is None:
                return False
            s = self.on['base'] if s == 'base' else self.on['stand']
        return False

    def _submerge(self, h):
        oy = self.outlet_y()
        if oy is None or not self.over_bin('tankA'):
            return h
        d = self.bin_surface_y - oy
        return h - d if d > 0 else h

    def q_valve(self):
        if not (self.valve and self.on['tankA']):
            return 0.0
        h = self._submerge(self.head_at(+5.0, +2.5))
        if h <= H_STOP4:
            return 0.0
        return A_VALVE * self.kv * self.run_jit['valve'] * h ** XV

    def q_hole4(self):
        if self.plugA4 or not self.on['tankA']:
            return 0.0
        h = self._submerge(self.head_at(+1.5, -5.0))
        if h <= H_STOP4:
            return 0.0
        return A_HOLE4 * self.cd4 * self.run_jit['h4'] * math.sqrt(2 * G * h)

    def q_hole5(self):
        if self.plugA5 or not self.on['tankA']:
            return 0.0
        h = self._submerge(self.head_at(-1.5, -5.0))
        if h <= H_STOP5:
            return 0.0
        return A_HOLE5 * self.cd5 * self.run_jit['h5'] * math.sqrt(2 * G * h)

    def q_tankB(self):
        if self.plugB or not self.on['tankB']:
            return 0.0
        h = self.hB
        if h <= H_STOP5:
            return 0.0
        return A_HOLE5 * self.cdb * math.sqrt(2 * G * h)

    def jet_land(self):
        """Where the stream leaving tank A strikes: it flies further while the
        tank is full, and creeps back towards the wall as the level falls."""
        if not self.on['tankA']:
            return None
        sl = self.slot('tankA')
        oy = self.outlet_y()
        inside = self.over_bin('tankA')
        yl = BIN_FLOOR + self.bin_depth if inside else 0.0
        t = math.sqrt(max(0.0, 2.0 * (oy - yl)) / G)
        best = None
        for q, area, x0, z0, vx, vz in ((self.q_valve(), A_VALVE, sl[0] + TANK_W + 2 * WALL + 2.6, sl[1] + WALL + 8.0, 1.0, 0.0), (self.q_hole4(), A_HOLE4, sl[0] + WALL + 6.5, sl[1] - 1.0, 0.0, -1.0), (self.q_hole5(), A_HOLE5, sl[0] + WALL + 3.5, sl[1] - 1.0, 0.0, -1.0)):
            if q <= 0.5:
                continue
            v = q / area
            x, z = (x0 + v * vx * t, z0 + v * vz * t)
            if inside:
                x = min(x, BIN_X1 - BIN_WALL - 0.5)
                z = max(z, BIN_Z0 + BIN_WALL + 0.5)
            if best is None or q > best[2]:
                best = (x, z, q)
        return (best[0], best[1]) if best else None

    def b_jet(self):
        """where the jet leaving tank B lands: (x, y, z, v) or None."""
        if not self.on['tankB']:
            return None
        sl = self.slot('tankB')
        y0 = self.obj_y('tankB') + WALL + B_HOLE_Z
        x0 = sl[0] + TANK_W + 2 * WALL
        z0 = sl[1] + WALL + TANK_D / 2.0
        q = self.q_tankB()
        return (x0, y0, z0, q / A_HOLE5 if q > 0 else 0.0)

    def b_feeds_a(self):
        """does that jet actually fall into the mouth of tank A?"""
        j = self.b_jet()
        if not j or j[3] <= 0 or (not self.on['tankA']):
            return False
        x0, y0, z0, v = j
        sa = self.slot('tankA')
        ya = self.obj_y('tankA')
        ysurf = ya + WALL + max(0.0, self.VA / self.area)
        if ysurf >= y0:
            return False
        t = math.sqrt(2.0 * (y0 - ysurf) / G)
        xl = x0 + v * t
        return sa[0] + WALL <= xl <= sa[0] + WALL + TANK_W and sa[1] + WALL <= z0 <= sa[1] + WALL + TANK_D
    CAP = {'tankA': A_CAP + 200.0, 'tankB': B_CAP + 200.0, 'bin': BIN_AREA * BIN_H, 'beaker': BEAKER_CAP, 'bottle1': BOTTLE_CAP, 'bottle2': BOTTLE_CAP}

    def tilt_angle(self):
        return math.radians(18.0 + 112.0 * self.pour_tilt)

    def head_over_lip(self):
        """how deep the water stands above the lip of the vessel being poured
        (negative = the lip is above the surface, so nothing comes out)."""
        if not self.pouring:
            return 0.0
        src = self.pouring[0]
        if src not in ('bottle1', 'bottle2', 'beaker'):
            return 0.0
        poly, lip, cap = vessel_geom(src)
        a = -self.tilt_angle()
        P = rot(poly, a)
        L = rot((lip,), a)[0]
        d = fill_line(P, self.vol(src) / cap)
        return d - L[1]

    @property
    def pour_rate(self):
        """Poured out of a hand-held vessel the flow is set by the geometry:
        a PET bottle empties through its 22 mm neck, the beaker as a sheet over
        its lip.  Dipping a beaker into a container simply scoops."""
        if not self.pouring:
            return 0.0
        src = self.pouring[0]
        if src in ('bottle1', 'bottle2', 'beaker'):
            self.pour_head = self.head_over_lip()
        h = max(0.0, self.pour_head)
        if src in ('bottle1', 'bottle2'):
            return CD_NECK * A_NECK * math.sqrt(2.0 * G * h)
        if src == 'beaker':
            return CD_LIP * A_LIP * math.sqrt(2.0 * G * h)
        return 150.0

    def fall_time(self):
        return math.sqrt(2.0 * max(0.5, self.pour_drop) / G)

    def overflowing(self, tank):
        """is that tank spilling over its rim right now?"""
        if tank == 'tankA':
            return self.on['tankA'] and self.VA >= A_CAP - 0.5 and (self._inflow('tankA') > 0.5)
        return self.on['tankB'] and self.VB >= B_CAP - 0.5 and (self._inflow('tankB') > 0.5)

    def _inflow(self, cid):
        q = 0.0
        if self.pouring and self.pouring[1] == cid:
            q += self.pour_rate
        for v, ta, dst in self.inflight:
            if dst == cid:
                q += 1.0
        if cid == 'tankA' and self.b_feeds_a():
            q += self.q_tankB()
        return q

    def vol(self, cid):
        return {'tankA': self.VA, 'tankB': self.VB, 'bin': self.Vbin, 'beaker': self.beaker, 'bottle1': self.bottle[0], 'bottle2': self.bottle[1]}.get(cid, 0.0)

    def pending(self, cid):
        """water already on its way down towards this container."""
        return sum((pl[0] for pl in self.inflight if pl[2] == cid))

    def room(self, cid):
        return max(0.0, self.CAP.get(cid, 0.0) - self.vol(cid) - self.pending(cid))

    def add(self, cid, v):
        if cid == 'tankA':
            self.VA += v
        elif cid == 'tankB':
            self.VB += v
        elif cid == 'bin':
            self.Vbin += v
        elif cid == 'beaker':
            self.beaker += v
        elif cid == 'bottle1':
            self.bottle[0] += v
        elif cid == 'bottle2':
            self.bottle[1] += v
        else:
            x, z = self._spill_xz or (26.0, -7.0)
            self.spill(v, x, z)

    @property
    def puddle(self):
        return sum((pd[2] for pd in self.puddles))

    @property
    def spilled(self):
        return self.puddle + self.wiped

    def spill(self, v, x, z):
        """water hits the bench at (x, z) and starts to spread from there."""
        if v <= 0.0:
            return
        for pd in self.puddles:
            if (pd[0] - x) ** 2 + (pd[1] - z) ** 2 < (pd[3] + 2.0) ** 2:
                pd[2] += v
                return
        self.puddles.append([x, z, v, 0.4])

    def wipe(self, v=250.0, x=None, z=None):
        """mop the bench with the towel;  the water is NOT recoverable."""
        if not self.puddles:
            return 0.0
        if x is None:
            i = max(range(len(self.puddles)), key=lambda k: self.puddles[k][2])
        else:
            i = min(range(len(self.puddles)), key=lambda k: (self.puddles[k][0] - x) ** 2 + (self.puddles[k][1] - z) ** 2)
        pd = self.puddles[i]
        got = min(v, pd[2])
        pd[2] -= got
        self.wiped += got
        self.towel_wet = min(1.0, self.towel_wet + got / 400.0)
        if pd[2] < 0.5:
            self.puddles.pop(i)
        return got

    def take(self, cid, v):
        v = min(v, self.vol(cid))
        self.add(cid, -v)
        return v

    def step(self, dt, sub=0.01):
        if dt <= 0:
            return
        n = max(1, int(math.ceil(dt / sub)))
        h = dt / n
        for _ in range(n):
            self._one(h)

    def _one(self, dt):
        self.t += dt
        in_bin = self.on['base'] == 'bin' or self.on['stand'] == 'bin' or self.on['tankA'] == 'bin'
        if in_bin and self.bin_depth > FLOAT_DEPTH:
            a = min(0.03, 0.05 * (self.bin_depth - FLOAT_DEPTH))
            self.wobble = a * math.sin(2.2 * self.t) + 0.4 * a * math.sin(5.7 * self.t + 1.0)
        else:
            self.wobble = 0.0
        if self.pouring:
            src, dst = self.pouring
            v = min(self.pour_rate * dt, self.vol(src), self.room(dst))
            if self.vol(src) <= 1e-09 or self.room(dst) <= 1e-09:
                self.pouring = None
            elif v > 1e-09:
                self.take(src, v)
                ta = self.t + self.fall_time()
                if self.inflight and self.inflight[-1][2] == dst and (ta - self.inflight[-1][1] < 0.02):
                    self.inflight[-1][0] += v
                else:
                    self.inflight.append([v, ta, dst])
        if self.inflight:
            keep = []
            for parcel in self.inflight:
                if parcel[1] <= self.t:
                    self.add(parcel[2], parcel[0])
                    if parcel[2] in self.surge:
                        self.surge[parcel[2]] += parcel[0]
                else:
                    keep.append(parcel)
            self.inflight = keep
        if self.pumping and self.pump_in and self.pump_out:
            ph = self.t % PUMP_STROKE_T / PUMP_STROKE_T
            f = max(0.0, math.sin(math.pi * ph)) * (math.pi / 2.0)
            if self.vol(self.pump_in) <= 1e-09 or self.room(self.pump_out) <= 1e-09:
                self.pumping = False
            else:
                v = min(PUMP_RATE * f * dt, self.vol(self.pump_in), self.room(self.pump_out))
                self.take(self.pump_in, v)
                self.add(self.pump_out, v)
        qb = self.q_tankB()
        if qb > 0:
            v = self.take('tankB', qb * dt)
            j = self.b_jet()
            if self.b_feeds_a():
                sa = self.slot('tankA')
                self.land['tankA'] = (sa[0] + 8.0, sa[1] + 5.5)
                self.add('tankA', v)
            elif self.over_bin('tankB'):
                self.land['bin'] = (j[0] + 8.0, j[2]) if j else (26.0, 12.0)
                self.add('bin', v)
            else:
                self._spill_xz = (j[0] + 8.0, j[2] - 3.0) if j else None
                self.add('spill', v)
                self._spill_xz = None
        q = self.q_valve() + self.q_hole4() + self.q_hole5()
        if q > 0:
            v = self.take('tankA', q * dt)
            px = self.jet_land() or (26.0, 10.0)
            if self.over_bin('tankA'):
                self.land['bin'] = px
                self.add('bin', v)
            else:
                self._spill_xz = (px[0], px[1] - 6.0)
                self.add('spill', v)
                self._spill_xz = None
        for tank, cap in (('tankA', A_CAP), ('tankB', B_CAP)):
            vol = self.VA if tank == 'tankA' else self.VB
            if vol > cap:
                over = vol - cap
                if tank == 'tankA':
                    self.VA = cap
                else:
                    self.VB = cap
                sl = self.slot(tank)
                if self.over_bin(tank):
                    if sl:
                        self.land['bin'] = (sl[0] + 5.5, sl[1] - 2.0)
                    self.add('bin', over)
                else:
                    self._spill_xz = (sl[0] + 5.5, sl[1] - 3.0) if sl else None
                    self.add('spill', over)
                    self._spill_xz = None
        for k in self.slosh:
            if self.slosh[k] > 0.0:
                self.slosh[k] = max(0.0, self.slosh[k] - 3.0 * dt)
        for pd in self.puddles:
            req = math.sqrt(max(pd[2], 1.0) / (math.pi * PUDDLE_T))
            pd[3] = min(req, pd[3] + PUDDLE_SPREAD * dt) if pd[3] < req else req
        for k in self.surge:
            if self.surge[k] > 1e-06:
                h = max(1.0, (self.VA if k == 'tankA' else self.VB) / self.area)
                tau = max(0.001, TANK_D / (2.0 * math.sqrt(G * h)))
                self.surge[k] *= math.exp(-dt / tau)
                if self.surge[k] < 1e-06:
                    self.surge[k] = 0.0
        if self.beaker > BEAKER_CAP:
            self.add('puddle', self.beaker - BEAKER_CAP)
            self.beaker = BEAKER_CAP
        for i in (0, 1):
            if self.bottle[i] > BOTTLE_CAP:
                self.add('puddle', self.bottle[i] - BOTTLE_CAP)
                self.bottle[i] = BOTTLE_CAP
        self.VA = max(0.0, self.VA)
        self.VB = max(0.0, self.VB)

    def total_water(self):
        return self.VA + self.VB + self.Vbin + self.beaker + self.puddle + self.wiped + self.bottle[0] + self.bottle[1] + sum((pl[0] for pl in self.inflight))
